import random

def transform(grid):
    n=len(grid)
    palette=sorted({v for row in grid for v in row})
    # ARC examples show a doubled grid whose top-left quadrant is the input;
    # fill other quadrants with values from the same color palette.
    out=[[0]*(2*n) for _ in range(2*n)]
    for r in range(n):
        for c in range(n):
            out[r][c]=grid[r][c]
    for r in range(n):
        for c in range(n,2*n):
            out[r][c]=random.choice(palette)
    for r in range(n,2*n):
        for c in range(2*n):
            out[r][c]=random.choice(palette)
    return out
